class GameEngine:
    OPS = {
        ">=": lambda a, b: a >= b,
        "<=": lambda a, b: a <= b,
        ">": lambda a, b: a > b,
        "<": lambda a, b: a < b,
        "==": lambda a, b: a == b,
        "!=": lambda a, b: a != b,
    }

    def __init__(self, story, start, variables, inventory):
        self.story = story
        self.start = start
        self.base_vars = dict(variables)
        self.base_items = set(inventory)

    def fresh_state(self):
        return {
            "vars": dict(self.base_vars),
            "items": set(self.base_items),
            "node": self.start,
            "log": [],
        }

    def check(self, cond, state):
        if not cond:
            return True
        if "item" in cond and cond["item"] not in state["items"]:
            return False
        if "no_item" in cond and cond["no_item"] in state["items"]:
            return False
        for key, op, value in cond.get("vars", []):
            if not self.OPS[op](state["vars"].get(key, 0), value):
                return False
        return True

    def apply(self, effects, state):
        if not effects:
            return
        for key, value in effects.get("set", {}).items():
            state["vars"][key] = value
        for key, value in effects.get("add", {}).items():
            state["vars"][key] = state["vars"].get(key, 0) + value
        state["items"].update(effects.get("items", []))
        for item in effects.get("remove_items", []):
            state["items"].discard(item)

    def render(self, text, state):
        for key, value in state["vars"].items():
            text = text.replace("{" + key + "}", str(value))
        return text

    def run(self):
        print("=== THE EMBER GATE — an interactive story ===")
        while True:
            self.play(self.fresh_state())
            if input("\nPlay again? (y/n) > ").strip().lower() != "y":
                print("Farewell, traveler.")
                break

    def play(self, state):
        while True:
            node = self.story[state["node"]]
            print("\n" + "-" * 60)
            print(self.render(node["text"], state))
            if node.get("ending"):
                self.finish(node, state)
                return
            choices = [c for c in node["choices"] if self.check(c.get("if"), state)]
            for i, choice in enumerate(choices, 1):
                print(f"  {i}. {choice['text']}")
            pick = self.ask(len(choices))
            choice = choices[pick - 1]
            state["log"].append(choice["text"])
            self.apply(choice.get("effects"), state)
            state["node"] = choice["next"]

    def ask(self, count):
        while True:
            raw = input("> ").strip()
            if raw.isdigit() and 1 <= int(raw) <= count:
                return int(raw)
            print(f"Enter a number between 1 and {count}.")

    def finish(self, node, state):
        print("\n*** " + node["title"] + " ***")
        epi = node.get("epilogue_if")
        if epi and self.check(epi["if"], state):
            print(self.render(epi["text"], state))
        print("\n— Journey record —")
        for step in state["log"]:
            print(" • " + step)
        print("\nFinal trust: {trust} | courage: {courage} | gold: {gold}".format(**state["vars"]))
        print("Inventory: " + (", ".join(sorted(state["items"])) or "(empty)"))
